export interface DirectVerifyResult {
  token: string
  expiresAt: number
}

export type DirectVerifyErrorCode = number | 'timeout' | 'socket'

export class DirectVerifyError extends Error {
  readonly code: DirectVerifyErrorCode

  constructor(code: DirectVerifyErrorCode, message: string) {
    super(message)
    this.name = 'DirectVerifyError'
    this.code = code
  }
}

/** The minimal WebSocket surface the verifier needs, so tests can fake it. */
export interface WebSocketLike {
  onopen: ((event: Event) => void) | null
  onmessage: ((event: MessageEvent) => void) | null
  onerror: ((event: Event) => void) | null
  onclose: ((event: CloseEvent) => void) | null
  send(data: string): void
  close(): void
}

export type WebSocketFactory = (url: string) => WebSocketLike

interface VerifyMessage {
  type?: unknown
  payload?: unknown
}

function parseMessage(data: unknown): VerifyMessage | null {
  if (typeof data !== 'string') return null
  try {
    const parsed: unknown = JSON.parse(data)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return null
    }
    return parsed as VerifyMessage
  } catch {
    return null
  }
}

/**
 * Verifies a one-time code against a plugin signaling WebSocket.
 *
 * The connection is short-lived: it opens, sends `verify`, waits for exactly
 * one `token` or `error` answer and is closed again in every case. The token
 * returned here stays valid for the later `join` and for reconnects.
 */
export async function verifyCodeOverWebSocket(
  wsUrl: string,
  code: string,
  timeoutMs = 10_000,
  webSocketFactory: WebSocketFactory = (url) => new WebSocket(url),
): Promise<DirectVerifyResult> {
  let socket: WebSocketLike
  try {
    socket = webSocketFactory(wsUrl)
  } catch (err) {
    throw new DirectVerifyError(
      'socket',
      err instanceof Error ? err.message : 'Could not open WebSocket',
    )
  }

  let timer: ReturnType<typeof setTimeout> | null = null

  try {
    return await new Promise<DirectVerifyResult>((resolve, reject) => {
      let settled = false

      const finish = (settle: () => void) => {
        if (settled) return
        settled = true
        settle()
      }

      const fail = (error: DirectVerifyError) => finish(() => reject(error))
      const succeed = (result: DirectVerifyResult) => finish(() => resolve(result))

      timer = setTimeout(() => {
        fail(new DirectVerifyError('timeout', 'Code verification timed out'))
      }, timeoutMs)

      socket.onopen = () => {
        try {
          socket.send(JSON.stringify({ type: 'verify', payload: { code } }))
        } catch (err) {
          fail(
            new DirectVerifyError(
              'socket',
              err instanceof Error ? err.message : 'Could not send verify',
            ),
          )
        }
      }

      socket.onmessage = (event) => {
        const message = parseMessage(event.data)
        if (!message) return

        if (message.type === 'token') {
          const payload = message.payload as { token?: unknown; expiresAt?: unknown } | null
          if (
            payload &&
            typeof payload.token === 'string' &&
            typeof payload.expiresAt === 'number' &&
            Number.isFinite(payload.expiresAt)
          ) {
            succeed({ token: payload.token, expiresAt: payload.expiresAt })
          }
          return
        }

        if (message.type === 'error') {
          const payload = message.payload as { code?: unknown; message?: unknown } | null
          const codeValue =
            typeof payload?.code === 'number' && Number.isFinite(payload.code)
              ? payload.code
              : 0
          const text =
            typeof payload?.message === 'string' && payload.message
              ? payload.message
              : `Code verification failed (${codeValue})`
          fail(new DirectVerifyError(codeValue, text))
        }
      }

      socket.onerror = () => {
        fail(new DirectVerifyError('socket', 'WebSocket error during code verification'))
      }

      // A close without a prior answer means the server never replied.
      socket.onclose = () => {
        fail(new DirectVerifyError('socket', 'WebSocket closed before the code was verified'))
      }
    })
  } finally {
    if (timer !== null) clearTimeout(timer)
    socket.close()
  }
}
