import { parsePeerJsTarget } from './PeerJsTarget'

/**
 * Where a voice connection should go.
 *
 * `peerjs` is the serverless path: the 10-character code is the plugin's peer
 * ID. `direct` is used when the invite carries an explicit signaling URL
 * (`?ws=…`); the code is then verified over that WebSocket instead.
 */
export type ConnectionTarget =
  | { mode: 'peerjs'; peerId: string; code: string }
  | { mode: 'direct'; wsUrl: string; code: string }

const MAX_SIGNALING_URL_LENGTH = 300
const DEFAULT_SIGNALING_PATH = '/signaling'

/**
 * Validates and normalizes a signaling URL.
 *
 * Accepted are only `ws:`/`wss:` URLs without credentials, query or fragment.
 * An empty path (or `/`) is the origin root, so the plugin's default endpoint
 * `/signaling` is used. On an HTTPS page plain `ws:` is rejected because the
 * browser blocks mixed content; on HTTP (local development) both are allowed.
 *
 * Returns `null` for anything invalid instead of throwing, so form validation
 * can call it on every keystroke.
 */
export function parseSignalingUrl(
  raw: string,
  pageProtocol: string,
): string | null {
  const value = raw.trim()
  if (!value || value.length > MAX_SIGNALING_URL_LENGTH) return null

  let url: URL
  try {
    url = new URL(value)
  } catch {
    return null
  }

  if (url.protocol !== 'ws:' && url.protocol !== 'wss:') return null

  // Credentials must not be embedded in a shareable invite link.
  if (url.username || url.password) return null

  // Tokens belong in the verify message, not in the URL.
  if (url.search || url.hash) return null

  // Guard against bare `?`/`#` which the URL parser normalizes away.
  if (value.includes('?') || value.includes('#')) return null

  if (!url.hostname) return null

  if (pageProtocol === 'https:' && url.protocol !== 'wss:') return null

  if (!url.pathname || url.pathname === '/') {
    url.pathname = DEFAULT_SIGNALING_PATH
  }

  return url.toString()
}

/**
 * Resolves the connection target for a code and an optional `?ws=` parameter.
 *
 * Priority: a valid signaling URL plus a valid 10-character code selects the
 * direct mode; otherwise a valid code uses PeerJS. Anything else returns
 * `null`, which the login form treats as "not submittable".
 */
export function resolveConnectionTarget(
  rawCode: string,
  wsParam: string | null | undefined,
  pageProtocol: string,
): ConnectionTarget | null {
  const peer = parsePeerJsTarget(rawCode)
  if (!peer) return null

  if (typeof wsParam === 'string') {
    const wsUrl = parseSignalingUrl(wsParam, pageProtocol)
    if (wsUrl) {
      return { mode: 'direct', wsUrl, code: peer.code }
    }
  }

  return { mode: 'peerjs', peerId: peer.peerId, code: peer.code }
}
