<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { normalizeVoiceCode, parsePeerJsTarget } from '@/voice/PeerJsTarget'
import { resolveConnectionTarget, parseSignalingUrl } from '@/voice/ConnectionTarget'
import { DirectVerifyError, verifyCodeOverWebSocket } from '@/auth/directVerify'
import { readTokenIdentity } from '@/auth/jwt'
import type { User } from '@/types'
import { safeRedirect } from '@/utils/safeRedirect'
import { t } from '@/i18n'
import BuildBadge from '@components/BuildBadge.vue'

const router = useRouter()
const route = useRoute()
const authStore = useAuthStore()
const voiceStore = useVoiceStore()

// Code input state
const code = ref('')
const error = ref<string | null>(null)
const isLoading = ref(false)
const isConnecting = ref(false)

// Computed
const codeLength = computed(() => code.value.length)
const wsParam = computed(() => {
  const value = route.query['ws']
  return typeof value === 'string' ? value : null
})
const connectionTarget = computed(() =>
  resolveConnectionTarget(code.value, wsParam.value, window.location.protocol),
)
const isCodeValid = computed(() => connectionTarget.value !== null)
const directHost = computed(() => {
  const ws = wsParam.value
  if (!ws) return null
  const url = parseSignalingUrl(ws, window.location.protocol)
  if (!url) return null
  try {
    return new URL(url).host
  } catch {
    return null
  }
})
const canSubmit = computed(() => isCodeValid.value && !isLoading.value && !isConnecting.value)

// Extract code from URL (query param ?code= or hash #/join/12345)
function extractCodeFromUrl(): string | null {
  // Check query parameter ?code=12345
  const routeQueryCode = route.query['code']
  const queryCode = typeof routeQueryCode === 'string'
    ? routeQueryCode
    : new URLSearchParams(window.location.search).get('code') ?? undefined
  if (queryCode && parsePeerJsTarget(queryCode)) {
    return normalizeVoiceCode(queryCode)
  }

  // Check hash route /join/12345
  const hashCode = route.params['code'] as string | undefined
  if (hashCode && parsePeerJsTarget(hashCode)) {
    return normalizeVoiceCode(hashCode)
  }

  // Check full hash #/join/12345 (for client-side routing)
  if (window.location.hash) {
    const hashMatch = window.location.hash.match(/#\/join\/([^/?]+)/i)
    if (hashMatch) {
      return normalizeVoiceCode(hashMatch[1] ?? '')
    }
  }

  return null
}

// Copy code to clipboard
async function copyCode() {
  if (!code.value) return
  try {
    await navigator.clipboard.writeText(code.value)
    // Visual feedback
    const copyBtn = document.querySelector('.btn-copy')
    copyBtn?.classList.add('copied')
    setTimeout(() => copyBtn?.classList.remove('copied'), 1500)
  } catch {
    // Fallback for older browsers
    const textarea = document.createElement('textarea')
    textarea.value = code.value
    textarea.style.position = 'fixed'
    textarea.style.opacity = '0'
    document.body.appendChild(textarea)
    textarea.select()
    document.execCommand('copy')
    document.body.removeChild(textarea)
  }
}

// Keep the server peer ID and normalize only the local code part.
function handleCodeInput(event: Event) {
  const input = event.target as HTMLInputElement
  const value = normalizeVoiceCode(input.value).slice(0, 10)
  code.value = value
  input.value = value
  error.value = null
}

// Handle paste event
function handlePaste(event: ClipboardEvent) {
  const pasted = event.clipboardData?.getData('text') ?? ''
  const pastedCode = normalizeVoiceCode(pasted).slice(0, 10)
  if (pastedCode) {
    event.preventDefault()
    code.value = pastedCode
    error.value = null
  }
}

// Direct mode has no profile in the verify answer. Decoding the token payload
// is best effort for display only; it never authorizes anything.
function directUserFromToken(token: string): User {
  const identity = readTokenIdentity(token)
  const name = identity.name ?? 'Minecraft-Spieler'
  const now = new Date().toISOString()
  return {
    id: identity.id ?? 'direct-pending',
    username: name,
    displayName: name,
    createdAt: now,
    updatedAt: now,
  }
}

// Submit code and connect
async function handleSubmit() {
  if (!isCodeValid.value || isLoading.value) return

  error.value = null
  isLoading.value = true

  const target = connectionTarget.value
  if (!target) {
    isLoading.value = false
    return
  }

  try {
    isConnecting.value = true
    if (target.mode === 'peerjs') {
      const peerHost = import.meta.env.VITE_PEERJS_HOST || '0.peerjs.com'
      authStore.preparePeerJsAuth(code.value)
      await voiceStore.connect({
        mode: 'peerjs',
        pluginPeerId: target.peerId,
        host: peerHost,
        port: Number(import.meta.env.VITE_PEERJS_PORT || 443),
        path: import.meta.env.VITE_PEERJS_PATH || '/',
        secure: import.meta.env.VITE_PEERJS_SECURE !== 'false',
        key: import.meta.env.VITE_PEERJS_KEY || 'peerjs',
        token: import.meta.env.VITE_PEERJS_TOKEN || '',
        code: target.code,
      })
    } else {
      const { token } = await verifyCodeOverWebSocket(target.wsUrl, target.code)
      authStore.setAuth(
        { user: directUserFromToken(token), token },
        { sessionOnly: true },
      )
      await voiceStore.connect({
        mode: 'server',
        url: target.wsUrl,
        token,
        // Deliberate: the same default channel the PeerJS path uses
        // (setCurrentChannel('minecraft')), so both modes join one room.
        roomId: 'minecraft',
        displayName: authStore.username,
      })
    }
    await router.push(targetAfterLogin())

  } catch (err) {
    let message: string
    if (err instanceof DirectVerifyError) {
      if (err.code === 1009) {
        message = t('login.error.expired')
      } else if (err.code === 1029) {
        message = t('login.error.rateLimited')
      } else {
        message = err.message || t('login.error.connect')
      }
    } else {
      const rawMessage = err instanceof Error ? err.message : t('login.error.connect')
      message = /could not connect to peer|peer unavailable/i.test(rawMessage)
        ? t('login.error.expired')
        : rawMessage
    }
    if (authStore.token?.startsWith('peerjs:')) authStore.clearAuth()
    error.value = message
    isConnecting.value = false
  } finally {
    isLoading.value = false
  }
}

// A guarded link such as /app/#/voice remembers where the user wanted to go.
function targetAfterLogin(): string {
  return safeRedirect(route.query['redirect']) ?? '/voice'
}

// Handle Enter key
function handleKeydown(event: KeyboardEvent) {
  if (event.key === 'Enter' && canSubmit.value) {
    handleSubmit()
  }
}

// Initialize on mount
onMounted(() => {
  authStore.restoreAuth()

  // Prefill the code input from the URL (?code= or #/join/<code>)
  const extractedCode = extractCodeFromUrl()
  if (extractedCode) {
    code.value = extractedCode
  }

  // If already authenticated and no code in URL, redirect to voice
  if (authStore.isAuthenticated && !extractedCode && route.name === 'Login') {
    router.push(targetAfterLogin())
  }
})

// Watch for route changes (e.g., user navigates to /join/12345 from within app)
watch(() => route.fullPath, () => {
  const extractedCode = extractCodeFromUrl()
  if (extractedCode) {
    code.value = extractedCode
  }
  // Don't clear code.value if the user typed it manually
})
</script>

<template>
  <div class="login-container">
    <div class="login-card">
      <div class="login-header">
        <h1>SimpleVoiceChat</h1>
        <BuildBadge />
        <p class="subtitle">{{ t('login.subtitle') }}</p>
      </div>

      <div class="instruction-card">
        <div class="instruction-icon" aria-hidden="true">
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
          </svg>
        </div>
        <div class="instruction-text">
          <p>{{ t('login.instructionBefore') }} <code>/voice link</code> {{ t('login.instructionAfter') }}</p>
          <p class="instruction-hint">{{ t('login.hint') }}</p>
        </div>
      </div>

      <div v-if="error" class="error-message" role="alert">
        {{ error }}
      </div>
      <form @submit.prevent="handleSubmit" class="login-form">
        <div class="form-group">
          <label for="code" class="form-label">
            {{ t('login.codeLabel') }}
            <span class="code-counter">{{ codeLength }}</span>
          </label>
          <div class="code-input-wrapper">
            <input
              id="code"
              v-model="code"
              type="text"
            inputmode="text"
            pattern="[A-Za-z0-9]{10}"
              maxlength="10"
              autocomplete="off"
              :disabled="isLoading || isConnecting"
              @input="handleCodeInput"
              @paste="handlePaste"
              @keydown="handleKeydown"
              placeholder="K7P4QX9LM2"
              aria-describedby="code-hint"
            />
            <button
              type="button"
              class="btn-copy"
              @click="copyCode"
              :disabled="!code || isLoading"
              :aria-label="t('login.copyAria')"
              :title="t('login.copyTitle')"
            >
              <svg class="copy-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
              </svg>
              <svg class="copied-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                <polyline points="20 6 9 17 4 12" />
              </svg>
            </button>
          </div>
          <p id="code-hint" class="form-hint">{{ t('login.codeHint') }}</p>
          <p v-if="directHost" class="form-hint direct-target">
            {{ t('login.directTarget', { host: directHost }) }}
          </p>
        </div>

        <button
          type="submit"
          class="btn btn-primary btn-block"
          :disabled="!canSubmit"
          :class="{ 'btn-loading': isConnecting }"
        >
          <span v-if="isConnecting" class="btn-spinner" aria-hidden="true"></span>
          <span v-if="isLoading && !isConnecting">{{ t('login.checking') }}</span>
          <span v-else-if="isConnecting">{{ t('login.connecting') }}</span>
          <span v-else>{{ t('login.join') }}</span>
        </button>
      </form>

      <div class="divider">
        <span>{{ t('login.or') }}</span>
      </div>

      <p class="footer-hint">
        {{ t('login.noServer') }} <a href="/docs/" target="_blank" rel="noopener noreferrer">{{ t('login.learnMore') }}</a>
      </p>
    </div>
  </div>
</template>

<style scoped src="./login-view.css"></style>
